/* STM32CubeU5 HAL SPI test.
 *
 * Unmodified HAL with a loopback slave attached to SPI1 and SPI3 by the robot test, so every
 * byte received equals the byte sent. SPI1 (full-featured) and SPI3 (limited) are master,
 * full duplex, software NSS, as generated by STM32CubeMX. Checks:
 * - SPI1, 8-bit frames, HAL_SPI_TransmitReceive (polling);
 * - SPI1, 8-bit frames, HAL_SPI_TransmitReceive_IT;
 * - SPI1, 16-bit frames, HAL_SPI_TransmitReceive;
 * - SPI3, 8-bit frames, HAL_SPI_TransmitReceive. */

#include <string.h>

#include "clock_160mhz.h"

SPI_HandleTypeDef hspi1;
SPI_HandleTypeDef hspi3;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t polling8Ok;
volatile uint32_t interrupt8Ok;
volatile uint32_t polling16Ok;
volatile uint32_t limited8Ok;
volatile uint32_t transferComplete;

static uint8_t tx8[16];
static uint8_t rx8[16];
static uint16_t tx16[8];
static uint16_t rx16[8];

void SysTick_Handler(void)
{
    HAL_IncTick();
}

void SPI1_IRQHandler(void)
{
    HAL_SPI_IRQHandler(&hspi1);
}

void HAL_SPI_TxRxCpltCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi == &hspi1)
    {
        transferComplete = 1u;
    }
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

void HAL_SPI_MspInit(SPI_HandleTypeDef *hspi)
{
    if (hspi->Instance == SPI1)
    {
        __HAL_RCC_SPI1_CLK_ENABLE();
        HAL_NVIC_SetPriority(SPI1_IRQn, 1, 0);
        HAL_NVIC_EnableIRQ(SPI1_IRQn);
    }
    else if (hspi->Instance == SPI3)
    {
        __HAL_RCC_SPI3_CLK_ENABLE();
    }
}

static HAL_StatusTypeDef spiInit(SPI_HandleTypeDef *hspi, SPI_TypeDef *instance, uint32_t dataSize)
{
    hspi->Instance = instance;
    hspi->Init.Mode = SPI_MODE_MASTER;
    hspi->Init.Direction = SPI_DIRECTION_2LINES;
    hspi->Init.DataSize = dataSize;
    hspi->Init.CLKPolarity = SPI_POLARITY_LOW;
    hspi->Init.CLKPhase = SPI_PHASE_1EDGE;
    hspi->Init.NSS = SPI_NSS_SOFT;
    hspi->Init.BaudRatePrescaler = SPI_BAUDRATEPRESCALER_16;
    hspi->Init.FirstBit = SPI_FIRSTBIT_MSB;
    hspi->Init.TIMode = SPI_TIMODE_DISABLE;
    hspi->Init.CRCCalculation = SPI_CRCCALCULATION_DISABLE;
    hspi->Init.CRCPolynomial = 0x7;
    hspi->Init.NSSPMode = SPI_NSS_PULSE_DISABLE;
    hspi->Init.NSSPolarity = SPI_NSS_POLARITY_LOW;
    hspi->Init.FifoThreshold = SPI_FIFO_THRESHOLD_01DATA;
    hspi->Init.MasterSSIdleness = SPI_MASTER_SS_IDLENESS_00CYCLE;
    hspi->Init.MasterInterDataIdleness = SPI_MASTER_INTERDATA_IDLENESS_00CYCLE;
    hspi->Init.MasterReceiverAutoSusp = SPI_MASTER_RX_AUTOSUSP_DISABLE;
    hspi->Init.MasterKeepIOState = SPI_MASTER_KEEP_IO_STATE_DISABLE;
    hspi->Init.IOSwap = SPI_IO_SWAP_DISABLE;
    hspi->Init.ReadyMasterManagement = SPI_RDY_MASTER_MANAGEMENT_INTERNALLY;
    hspi->Init.ReadyPolarity = SPI_RDY_POLARITY_HIGH;
    return HAL_SPI_Init(hspi);
}

static void fillPattern(uint32_t seed)
{
    for (uint32_t index = 0u; index < sizeof(tx8); ++index)
    {
        tx8[index] = (uint8_t)(seed + index * 17u);
        rx8[index] = 0u;
    }
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    check(spiInit(&hspi1, SPI1, SPI_DATASIZE_8BIT), 3);
    fillPattern(0x11u);
    check(HAL_SPI_TransmitReceive(&hspi1, tx8, rx8, sizeof(tx8), 100), 4);
    polling8Ok = memcmp(tx8, rx8, sizeof(tx8)) == 0;

    fillPattern(0x5Au);
    check(HAL_SPI_TransmitReceive_IT(&hspi1, tx8, rx8, sizeof(tx8)), 5);
    const uint32_t start = HAL_GetTick();
    while (!transferComplete)
    {
        if (HAL_GetTick() - start > 100u)
        {
            failedStep = 6;
            for (;;)
            {
            }
        }
    }
    interrupt8Ok = memcmp(tx8, rx8, sizeof(tx8)) == 0;

    check(HAL_SPI_DeInit(&hspi1), 7);
    check(spiInit(&hspi1, SPI1, SPI_DATASIZE_16BIT), 8);
    for (uint32_t index = 0u; index < 8u; ++index)
    {
        tx16[index] = (uint16_t)(0xA500u + index * 0x0111u);
        rx16[index] = 0u;
    }
    check(HAL_SPI_TransmitReceive(&hspi1, (uint8_t *)tx16, (uint8_t *)rx16, 8, 100), 9);
    polling16Ok = memcmp(tx16, rx16, sizeof(tx16)) == 0;

    check(spiInit(&hspi3, SPI3, SPI_DATASIZE_8BIT), 10);
    fillPattern(0xC3u);
    check(HAL_SPI_TransmitReceive(&hspi3, tx8, rx8, 8, 100), 11);
    limited8Ok = memcmp(tx8, rx8, 8) == 0;

    step = 12;
    for (;;)
    {
    }
}
